11	/// AD-2/AD-5 — the one network façade every repository's data source calls
12	/// through. Builds the real URL via `UrlBuilder`, sends the request through
13	/// `dio` (header + retry interceptors already attached in DI), and maps
14	/// every outcome — success or failure — to `Either<Failure, T>`; no
15	/// dio/native exception ever escapes unmapped (RNF09).
16	///
17	/// Tests mock this interface directly (per the architecture spine's testing
18	/// convention), not a fake transport layer underneath it.
19	class ApiClient {
20	  ApiClient({required Dio dio, required UrlBuilder urlBuilder})
21	      : _dio = dio,
22	        _urlBuilder = urlBuilder;
23	
24	  final Dio _dio;
25	  final UrlBuilder _urlBuilder;
26	
27	  Future<Either<Failure, Map<String, dynamic>>> get(
28	    String function, {
29	    List<String> pathParams = const [],
30	    Map<String, dynamic>? queryParameters,
31	  }) =>
32	      _send(
33	        () => _dio.get<Map<String, dynamic>>(
34	          _urlBuilder.build(function, pathParams),
35	          queryParameters: queryParameters,
36	        ),
37	      );
38	
39	  Future<Either<Failure, Map<String, dynamic>>> post(
40	    String function, {
41	    List<String> pathParams = const [],
42	    Object? data,
43	  }) =>
44	      _send(
45	        () => _dio.post<Map<String, dynamic>>(
46	          _urlBuilder.build(function, pathParams),
47	          data: data,
48	        ),
49	      );
50	
51	  Future<Either<Failure, Map<String, dynamic>>> patch(
52	    String function, {
53	    List<String> pathParams = const [],
54	    Object? data,
55	  }) =>
56	      _send(
57	        () => _dio.patch<Map<String, dynamic>>(
58	          _urlBuilder.build(function, pathParams),
59	          data: data,
60	        ),
61	      );
62	
63	  Future<Either<Failure, Map<String, dynamic>>> delete(
64	    String function, {
65	    List<String> pathParams = const [],
66	    Object? data,
67	  }) =>
68	      _send(
69	        () => _dio.delete<Map<String, dynamic>>(
70	          _urlBuilder.build(function, pathParams),
71	          data: data,
72	        ),
73	      );
74	
75	  Future<Either<Failure, Map<String, dynamic>>> _send(
76	    Future<Response<Map<String, dynamic>>> Function() request,
77	  ) async {
78	    try {
79	      final response = await request();
80	      final data = response.data;
81	      if (data == null) {
82	        return left(
83	          const Failure.malformedResponse(message: 'Empty response body'),
84	        );
85	      }
86	      return right(data);
87	    } on DioException catch (e) {
88	      return left(_mapDioException(e));
89	    } catch (e) {
90	      return left(Failure.malformedResponse(message: e.toString()));
91	    }
92	  }
93	
94	  Failure _mapDioException(DioException e) {
95	    final data = e.response?.data;
96	    if (data is Map && data['code'] is String) {
97	      return Failure.fromCode(
98	        data['code'] as String,
99	        (data['message'] as String?) ?? e.message ?? 'Unknown error',
100	      );
101	    }
102	    if (e.response == null) {
103	      // NETWORK_OFFLINE never produces an HTTP response at all
104	      // (error-taxonomy.md) — every connection-level dio error without a
105	      // response maps here.
106	      return Failure.networkOffline(
107	        message: e.message ?? 'No connection',
108	      );
109	    }
110	    return Failure.malformedResponse(message: e.message ?? 'Malformed response');
111	  }
112	}
