6	/// AD-5 — the one interceptor that owns every outgoing request's headers.
7	/// `apikey` is sent on every call. `Authorization` carries the anon key only
8	/// on the three `security: []` operations (signup, login, refresh) and the
9	/// user's access token on every other (`bearerAuth`) operation.
10	class HeaderInterceptor extends Interceptor {
11	  HeaderInterceptor({
12	    required String anonKey,
13	    required AccessTokenProvider accessTokenProvider,
14	  })  : _anonKey = anonKey,
15	        _accessTokenProvider = accessTokenProvider;
16	
17	  /// The three operations with `security: []` in the contract — the only
18	  /// ones that ever send the anon key as the bearer token.
19	  static const anonKeyOnlyFunctions = {
20	    'auth-signup',
21	    'auth-login',
22	    'auth-refresh',
23	  };
24	
25	  final String _anonKey;
26	  final AccessTokenProvider _accessTokenProvider;
27	
28	  @override
29	  void onRequest(
30	    RequestOptions options,
31	    RequestInterceptorHandler handler,
32	  ) async {
33	    options.headers['apikey'] = _anonKey;
34	
35	    final function = functionNameOf(options.path);
36	    if (anonKeyOnlyFunctions.contains(function)) {
37	      options.headers['Authorization'] = 'Bearer $_anonKey';
38	    } else {
39	      final userToken = await _accessTokenProvider.readAccessToken();
40	      if (userToken != null) {
41	        options.headers['Authorization'] = 'Bearer $userToken';
42	      }
43	    }
44	
45	    handler.next(options);
46	  }
47	
48	  /// The `x-cerne-function` name is always the first path segment of a URL
49	  /// built by `UrlBuilder` (whether [path] is the full absolute URL
50	  /// `ApiClient` sends to `dio`, or a bare `/function/...` path) — pure, so
51	  /// it's independently testable.
52	  static String functionNameOf(String path) {
53	    final segments = Uri.parse(path).pathSegments;
54	    return segments.isNotEmpty ? segments.first : '';
55	  }
56	}
