1	import 'package:dio/dio.dart';
2	
3	/// AD-4 — the one place retry policy lives. Retries only the 6 server
4	/// `retryable:true` codes (`error-taxonomy.md`); every other failure
5	/// (including the local `MalformedResponse`) surfaces once, unretried.
6	///
7	/// Design note (docs/input is silent on the schedule): fixed 500ms delay,
8	/// max 2 retries.
9	class RetryInterceptor extends Interceptor {
10	  RetryInterceptor(this._dio);
11	
12	  final Dio _dio;
13	
14	  /// The 6 server `retryable:true` codes — the only codes this interceptor
15	  /// ever retries.
16	  static const Set<String> retryableCodes = {
17	    'NETWORK_TIMEOUT',
18	    'NETWORK_OFFLINE',
19	    'PII_CHECK_FAILED',
20	    'EMBEDDING_FAILED',
21	    'AI_GENERATION_TIMEOUT',
22	    'RATE_LIMITED',
23	  };
24	
25	  static const int maxRetries = 2;
26	  static const Duration retryDelay = Duration(milliseconds: 500);
27	
28	  static const _attemptKey = 'cerne_retry_attempt';
29	
30	  @override
31	  void onError(DioException err, ErrorInterceptorHandler handler) async {
32	    final attempt = attemptOf(err);
33	
34	    if (shouldRetry(err, attempt)) {
35	      await Future<void>.delayed(retryDelay);
36	      final options = err.requestOptions;
37	      options.extra[_attemptKey] = attempt + 1;
38	      try {
39	        final response = await _dio.fetch<dynamic>(options);
40	        handler.resolve(response);
41	      } on DioException catch (retryError) {
42	        handler.next(retryError);
43	      }
44	      return;
45	    }
46	
47	    handler.next(err);
48	  }
49	
50	  /// How many retries have already been attempted for this request.
51	  static int attemptOf(DioException err) =>
52	      (err.requestOptions.extra[_attemptKey] as int?) ?? 0;
53	
54	  /// The backend error `code` for [err] — `NETWORK_OFFLINE` is the one code
55	  /// with no HTTP response at all (`error-taxonomy.md`); every other code is
56	  /// read from the response body `{code, message, retryable}`.
57	  static String? errorCodeOf(DioException err) {
58	    final data = err.response?.data;
59	    if (data is Map && data['code'] is String) {
60	      return data['code'] as String;
61	    }
62	    if (err.response == null) {
63	      return 'NETWORK_OFFLINE';
64	    }
65	    return null;
66	  }
67	
68	  /// Pure decision function, independently testable: retry only if the
69	  /// error's code is one of the 6 allowlisted codes and the max-retries
70	  /// budget isn't exhausted yet.
71	  static bool shouldRetry(DioException err, int attempt) {
72	    final code = errorCodeOf(err);
73	    return code != null && retryableCodes.contains(code) && attempt < maxRetries;
74	  }
75	}
