3	/// The port [HeaderInterceptor] reads the current user's access token
4	/// through. Owned by `core/` (not a feature) since the header-policy rule
5	/// (AD-5) is core infrastructure; the `auth` feature calls
6	/// [saveAccessToken]/[clearAccessToken] on login/logout once it exists
7	/// (Story 1.3/1.4) without this contract changing.
8	abstract class AccessTokenProvider {
9	  Future<String?> readAccessToken();
10	
11	  Future<void> saveAccessToken(String token);
12	
13	  Future<void> clearAccessToken();
14	}
15	
16	/// Default implementation, backed by `flutter_secure_storage` — the same
17	/// package this story's DI bootstrap integration test proves works end to
18	/// end through `get_it`.
19	class SecureStorageAccessTokenProvider implements AccessTokenProvider {
20	  SecureStorageAccessTokenProvider(this._storage);
21	
22	  static const _key = 'user_access_token';
23	
24	  final FlutterSecureStorage _storage;
25	
26	  @override
27	  Future<String?> readAccessToken() => _storage.read(key: _key);
28	
29	  @override
30	  Future<void> saveAccessToken(String token) =>
31	      _storage.write(key: _key, value: token);
32	
33	  @override
34	  Future<void> clearAccessToken() => _storage.delete(key: _key);
35	}
