12	/// The project's single `get_it` instance — exactly one DI container exists
13	/// (architecture spine). Every feature's `registerXFeature()` registers
14	/// through this same `sl`, never a second container.
15	final sl = GetIt.instance;
16	
17	/// Bootstraps core infrastructure: loads `.env`, then registers
18	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
19	/// interceptors) and `ApiClient` through `sl` — the `dio` +
20	/// `flutter_secure_storage` + `get_it` integration spike this story proves
21	/// before anything else is built on top of it.
22	Future<void> setupCoreDependencies() async {
23	  await dotenv.load(fileName: '.env');
24	
25	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
26	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
27	
28	  sl.registerLazySingleton<FlutterSecureStorage>(
29	    () => const FlutterSecureStorage(),
30	  );
31	
32	  sl.registerLazySingleton<AccessTokenProvider>(
33	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
34	  );
35	
36	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
37	
38	  sl.registerLazySingleton<Dio>(() {
39	    final dio = Dio();
40	    dio.interceptors.add(
41	      HeaderInterceptor(
42	        anonKey: supabaseAnonKey,
43	        accessTokenProvider: sl<AccessTokenProvider>(),
44	      ),
45	    );
46	    dio.interceptors.add(RetryInterceptor(dio));
47	    return dio;
48	  });
49	
50	  sl.registerLazySingleton<ApiClient>(
51	    () => ApiClient(dio: sl<Dio>(), urlBuilder: sl<UrlBuilder>()),
52	  );
53	}
54	
55	/// Test/teardown helper — resets the single `get_it` instance so each test
56	/// bootstraps its own clean registrations.
57	Future<void> resetCoreDependencies() => sl.reset();
