11	/// AC4 — proves the `dio` + `flutter_secure_storage` + `get_it` integration
12	/// spike works together in one bootstrap, before anything else is built on
13	/// top of it (architecture spine's Deferred note).
14	///
15	/// No device/simulator/CI exists yet to run a true platform-channel
16	/// integration test (AGENTS.md's "Running and verifying" TODO), so the
17	/// native secure-storage channel is faked with an in-memory store here —
18	/// the test still exercises the *real* `FlutterSecureStorage` instance
19	/// resolved from the single DI container, round-tripping a write/read
20	/// through it exactly as AC4 requires.
21	void main() {
22	  TestWidgetsFlutterBinding.ensureInitialized();
23	
24	  const secureStorageChannel = MethodChannel(
25	    'plugins.it_nomads.com/flutter_secure_storage',
26	  );
27	  final fakeNativeStorage = <String, String>{};
28	
29	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
30	    final args = call.arguments as Map<dynamic, dynamic>;
31	    switch (call.method) {
32	      case 'write':
33	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
34	        return null;
35	      case 'read':
36	        return fakeNativeStorage[args['key'] as String];
37	      case 'delete':
38	        fakeNativeStorage.remove(args['key'] as String);
39	        return null;
40	      case 'containsKey':
41	        return fakeNativeStorage.containsKey(args['key'] as String);
42	      default:
43	        return null;
44	    }
45	  }
46	
47	  setUp(() async {
48	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
49	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
50	
51	    await resetCoreDependencies();
52	    await setupCoreDependencies();
53	  });
54	
55	  tearDown(() async {
56	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
57	        .setMockMethodCallHandler(secureStorageChannel, null);
58	    fakeNativeStorage.clear();
59	    await resetCoreDependencies();
60	  });
61	
62	  test(
63	    'exactly one get_it instance resolves Dio + FlutterSecureStorage + ApiClient',
64	    () {
65	      expect(sl.isRegistered<Dio>(), isTrue);
66	      expect(sl.isRegistered<FlutterSecureStorage>(), isTrue);
67	      expect(sl.isRegistered<ApiClient>(), isTrue);
68	
69	      // `dio` is configured through the container: both interceptors
70	      // (header + retry, AD-4/AD-5) are attached to the resolved instance,
71	      // alongside dio's own built-in default interceptor.
72	      final dio = sl<Dio>();
73	      expect(dio.interceptors.whereType<HeaderInterceptor>(), hasLength(1));
74	      expect(dio.interceptors.whereType<RetryInterceptor>(), hasLength(1));
75	
76	      // Resolving twice returns the same singleton — one container, one Dio.
77	      expect(sl<Dio>(), same(dio));
78	    },
79	  );
