81	  test(
82	    'secure storage read/write round-trips through the DI-resolved instance',
83	    () async {
84	      final storage = sl<FlutterSecureStorage>();
85	
86	      await storage.write(key: 'spike_test_key', value: 'spike_test_value');
87	      final value = await storage.read(key: 'spike_test_key');
88	
89	      expect(value, 'spike_test_value');
