11	
12	DioException _errorWithCode(
13	  String code, {
14	  RequestOptions? requestOptions,
15	}) {
16	  final options = requestOptions ?? RequestOptions(path: '/some-function');
17	  return DioException(
18	    requestOptions: options,
19	    response: Response(
20	      requestOptions: options,
21	      statusCode: 502,
