54	      expect(RetryInterceptor.errorCodeOf(err), 'NETWORK_OFFLINE');
55	    });
56	  });
57	
58	  group('RetryInterceptor.shouldRetry — only the 6 retryable codes, AD-4', () {
59	    const retryableCodes = {
60	      'NETWORK_TIMEOUT',
61	      'NETWORK_OFFLINE',
62	      'PII_CHECK_FAILED',
63	      'EMBEDDING_FAILED',
64	      'AI_GENERATION_TIMEOUT',
65	      'RATE_LIMITED',
66	    };
67	
68	    const nonRetryableCodes = {
69	      'AUTH_EXPIRED',
70	      'AUTH_INVALID',
71	      'VALIDATION_ERROR',
72	      'NOT_FOUND',
73	      'EXPORT_EMPTY_PERIOD',
74	      'PAYLOAD_TOO_LARGE',
75	      'OCR_NO_TEXT',
76	    };
77	
78	    for (final code in retryableCodes) {
79	      test('$code retries on first attempt', () {
80	        final err = _errorWithCode(code);
81	        expect(RetryInterceptor.shouldRetry(err, 0), isTrue);
82	      });
83	    }
84	
85	    for (final code in nonRetryableCodes) {
86	      test('$code never retries', () {
87	        final err = _errorWithCode(code);
88	        expect(RetryInterceptor.shouldRetry(err, 0), isFalse);
89	      });
90	    }
91	
92	    test('stops retrying once maxRetries (2) is reached', () {
93	      final err = _errorWithCode('NETWORK_TIMEOUT');
94	      expect(RetryInterceptor.shouldRetry(err, 0), isTrue);
95	      expect(RetryInterceptor.shouldRetry(err, 1), isTrue);
96	      expect(RetryInterceptor.shouldRetry(err, 2), isFalse);
97	    });
98	  });
99	
100	  group('RetryInterceptor.onError — end-to-end retry behavior', () {
101	    late MockDio mockDio;
102	    late RetryInterceptor interceptor;
103	
104	    setUp(() {
105	      mockDio = MockDio();
106	      interceptor = RetryInterceptor(mockDio);
107	    });
108	
109	    test('retries a retryable error and resolves on success', () async {
110	      final options = RequestOptions(path: '/chat-messages-send');
111	      final err = _errorWithCode('AI_GENERATION_TIMEOUT', requestOptions: options);
112	      final successResponse = Response<dynamic>(
113	        requestOptions: options,
114	        statusCode: 200,
115	        data: {'ok': true},
116	      );
117	
118	      when(() => mockDio.fetch<dynamic>(any()))
119	          .thenAnswer((_) async => successResponse);
120	
121	      final handler = MockErrorInterceptorHandler();
122	      when(() => handler.resolve(any())).thenReturn(null);
123	
124	      interceptor.onError(err, handler);
125	      // Allow the 500ms delay + async fetch to complete.
126	      await Future<void>.delayed(const Duration(milliseconds: 700));
127	
128	      verify(() => mockDio.fetch<dynamic>(any())).called(1);
129	      verify(() => handler.resolve(successResponse)).called(1);
130	    });
131	
132	    test('never retries a non-retryable error', () async {
133	      final options = RequestOptions(path: '/auth-login');
134	      final err = _errorWithCode('AUTH_INVALID', requestOptions: options);
135	
136	      final handler = MockErrorInterceptorHandler();
137	      when(() => handler.next(any())).thenReturn(null);
138	
139	      interceptor.onError(err, handler);
140	      await Future<void>.delayed(const Duration(milliseconds: 50));
141	
142	      verifyNever(() => mockDio.fetch<dynamic>(any()));
143	      verify(() => handler.next(err)).called(1);
144	    });
145	  });
146	}
